import mq3.botlib.aas_clustering as c

function emptyWorld() settings=[];areas=[];for index=0 to 5 settings=settings+[c.areaSettings(0,0,0,0,0,0,0)];areas=areas+[c.area(0,0)] end for;value=c.world(true,true,[],[],[],[],[],[],areas,settings,[],false);value.portals=[c.portal(0,0,0,0,0),c.portal(0,0,0,0,0),c.portal(0,0,0,0,0)];value.clusters=[c.cluster(0,0,0,0),c.cluster(0,0,0,0),c.cluster(0,0,0,0),c.cluster(0,0,0,0)];return value end function
function main(args)
  value=emptyWorld();value.settings[1].cluster=1;value.settings[2].cluster=2;value.settings[3].cluster=2;value.settings[4].cluster=1;c.AAS_ClearCluster(value,2);print("clear:"+str(value.settings[1].cluster)+","+str(value.settings[2].cluster)+","+str(value.settings[3].cluster)+","+str(value.settings[4].cluster));c.AAS_RemoveClusterAreas(value);print("remove:"+str(value.settings[1].cluster)+","+str(value.settings[4].cluster))
  value.portals[1].areaNum=2;value.portals[1].frontCluster=1;value.portals[1].backCluster=2;value.portals[2].areaNum=4;value.portals[2].frontCluster=2;value.portals[2].backCluster=3;c.AAS_RemovePortalsClusterReference(value,2);print("refs:"+str(value.portals[1].frontCluster)+","+str(value.portals[1].backCluster)+","+str(value.portals[2].frontCluster)+","+str(value.portals[2].backCluster))
  value=emptyWorld();value.portals[1].areaNum=2;value.clusters[1].firstPortal=0;value.clusters[2].firstPortal=1;c.AAS_UpdatePortal(value,2,1);c.AAS_UpdatePortal(value,2,2);print("update:"+str(value.portals[1].frontCluster)+","+str(value.portals[1].backCluster)+","+str(value.settings[2].cluster)+","+str(value.clusters[1].numPortals)+","+str(value.clusters[2].numPortals));value.clusters[1].numAreas=3;value.clusters[1].firstPortal=0;value.clusters[1].numPortals=1;value.portalIndex[0]=1;c.AAS_NumberClusterPortals(value,1);print("number:"+str(value.portals[1].clusterAreaNums[0])+","+str(value.clusters[1].numAreas))
  value.settings[1].contents=c.AREACONTENTS_CLUSTERPORTAL;value.settings[2].contents=c.AREACONTENTS_CLUSTERPORTAL;c.AAS_CreateViewPortals(value);c.AAS_RemoveAllPortals(value);c.AAS_SetViewPortalsAsClusterPortals(value);print("view:"+str(value.settings[1].contents)+","+str(value.settings[2].contents));value.settings[2].contents=value.settings[2].contents|c.AREACONTENTS_CLUSTERPORTAL;value.portals[1].areaNum=2;value.portals[1].frontCluster=1;value.portals[1].backCluster=0;ok=c.AAS_TestPortals(value);okNumber=0;if ok then okNumber=1 end if;print("test:"+str(okNumber)+","+str(value.settings[2].contents));return 0
end function
